import React, { useState, useRef } from 'react';
import { FileUploader } from "react-drag-drop-files";
import { DIVISA } from '../tienda/tienda.js';

const FormularioNuevosProductos = ({ onAgregarProducto, deshabilitado }) => {
    const fileTypes = ["jpg", "png", "jpeg"];
    const [formData, setFormData] = useState({
        tipo: '',
        nombre: '',
        precio: '',
        descripcion: '',
        material: '',
        categoriajuguete: '',
        tipoAlimento: '',
        tipoMascota: '',
        categoria: '',
        estilo: ''
    });
    const [file, setFile] = useState(null);
    const [alerta, setAlerta] = useState({ visible: false, texto: "", tipo: "" });
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef(null);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const mostrarAlerta = (texto, tipo) => {
        setAlerta({ visible: true, texto, tipo });
        setTimeout(() => 
            setAlerta({ 
                visible: false, texto: "", tipo: "" 
            }), 3000);
    };

    const handleFile = (archivo) => {
        if (!archivo) return;
        // Si ya hay imagen
        if (file) {
            mostrarAlerta("Ya hay una imagen seleccionada. No puedes subir otra.", "danger");
            return;
        }
        // Validar formato
        const extension = archivo.name.split(".").pop().toLowerCase();
        if (!fileTypes.includes(extension)) {
            mostrarAlerta(
                "Formato no válido. La imagen debe ser JPG, JPEG, PNG o GIF.",
                "danger"
            );
            return;
        }
        setFile(archivo);
    };

    const renderCampoDinamico = () => {
        const configExtra = {
            'Mobiliario': { label: 'Material', name: 'material', ph: 'Ej: Madera, Roble...' },
            'Juguete': { label: 'Tipo de Juguete', name: 'categoriajuguete', ph: 'Ej: Peluche, Cuerda...' },
            'Alimentacion': { label: 'Tipo Alimento', name: 'tipoAlimento', ph: 'Ej: Snack, Pienso...' },
            'Accesorios': { label: 'Tipo de Mascota', name: 'tipoMascota', ph: 'Ej: Perro, Gato...' },
            'Cabello': { label: 'Estilo', name: 'estilo', ph: 'Ej: Pop, Moderno...' },
            'Merchandising': { label: 'Parte del Cuerpo', name: 'parteDelCuerpo', ph: 'Ej: Cabeza, Patas...' }
        };

        const config = configExtra[formData.tipo];
        if (!config) return null;

        return (
            <div className="mb-3 animate__animated animate__fadeIn">
                <label className="form-label fw-bold">{config.label}</label>
                <input 
                    type="text" 
                    className="form-control" 
                    name={config.name} 
                    value={formData[config.name]} 
                    onChange={handleChange} 
                    placeholder={config.ph} 
                    required 
                    disabled={deshabilitado} 
                />
            </div>
        );
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        //Offline
        if (deshabilitado) {
            mostrarAlerta("El formulario está deshabilitado", "danger");
            return;
        }

        if (!formData.tipo) {
            mostrarAlerta("Escoge un tipo", "danger");
            return;
        }

        let imagenUrl = null;
        if (file) {
            imagenUrl = URL.createObjectURL(file); 
        } else {
            imagenUrl = "/imagenes/productos/default.png"; 
        }

        const precioNum = parseFloat(formData.precio);
        const nuevoProducto = {
            id: "prod-" + Date.now(),
            ...formData,
            precio: precioNum,
            imagen: imagenUrl
        };

        onAgregarProducto(formData.tipo, nuevoProducto);
        mostrarAlerta("¡Producto añadido!", "success");
        // Reset del formulario
        setFormData({
            tipo: '',
            nombre: '',
            precio: '',
            descripcion: '',
            material: '',
            categoriajuguete: '',
            tipoAlimento: '',
            tipoMascota: '',
            categoria: '',
            estilo: ''
        });
        setFile(null);

        if (fileInputRef.current) {
            fileInputRef.current.value = ""; 
        }

        const primerInput = document.querySelector('#form-producto [name="tipo"]');
        if (primerInput) primerInput.focus();
    };

    return (
        <div className={`formulario-wrapper ${deshabilitado ? "offline-mode" : ""}`}> {/* cuando deshabilitado = true --> se ponen todos gris (heredan todos)*/}
            <h3 className="text-center mb-3">Añadir Productos</h3>
            <form id="form-producto" onSubmit={handleSubmit}>
                
                {/* Tipo de Producto */}
                <div className="mb-3">
                    <label className="form-label">Tipo de Producto</label>
                    <select name="tipo" className="form-select" value={formData.tipo} onChange={handleChange} required disabled={deshabilitado} style={styleOffline}>
                        <option value="">Escoge un tipo</option>
                        <option value="Mobiliario">Mobiliario</option>
                        <option value="Cabello">Cabello</option>
                        <option value="Juguete">Juguete</option>
                        <option value="Merchandising">Merchandising</option>
                        <option value="Alimentacion">Alimentación</option>
                        <option value="Accesorios">Accesorios</option>
                    </select>
                </div>

                {/* Nombre */}
                <div className="mb-3">
                    <label className="form-label">Nombre del Producto</label>
                    <input type="text" className="form-control" style={styleOffline} name="nombre" value={formData.nombre} onChange={handleChange} placeholder="Ej: Pelota de goma" required disabled={deshabilitado} />
                </div>

                {/* Precio */}
                <div className="mb-3">
                    <label className="form-label">Precio ({DIVISA})</label>
                    <input type="number" className="form-control" sytle={styleOffline} name="precio" value={formData.precio} onChange={handleChange} required disabled={deshabilitado} 
                        onKeyDown={(e) => { if (["e","E","+","-"].includes(e.key)) e.preventDefault(); }} step="0.01" min="0" placeholder="0.00" /> {/* Para que no permita las e ni nada de eso + que empiece en 0 y que incremente centimo a centimo si usas las flechas */}
                </div>


                {/* Descripción */}
                <div className="mb-3">
                    <label className="form-label">Descripción</label>
                    <textarea className="form-control" sytle={styleOffline} disabled={deshabilitado} name="descripcion" value={formData.descripcion} onChange={handleChange} placeholder="Describe tu producto..." rows="2"></textarea>
                </div>

                {renderCampoDinamico()}

                {/* Imagen upload */}
                <div className="mb-3">
                    <label className="form-label text-white">Imagen del Producto</label>
                    <input type="file" ref={fileInputRef} className="form-control" accept="image/*" disabled={deshabilitado} onChange={(e) => {
                        const archivos = e.target.files;
                            if (!archivos || archivos.length === 0) return;
                                if (archivos.length > 1) {
                                    mostrarAlerta("Solo puedes subir un archivo", "danger");
                                    return;
                                }
                                handleFile(archivos[0]);
                                }} 
                    />
                </div>

                {/* Imagen D&D */}
                <div className="mb-4">
                    <label className="form-label">O arrastra la imagen aquí</label>
                    <FileUploader
                        handleChange={(file) => handleFile(file)}
                        name="file"
                        types={fileTypes}
                        disabled={deshabilitado}
                        onDraggingStateChange={setIsDragging}
                        onTypeError={() =>
                            mostrarAlerta("Formato no válido. La imagen debe ser JPG, JPEG, PNG o GIF.", "danger")
                        }
                        /* Limpiamos textos por defecto de la librería */
                        hoverTitle=" " 
                        dropMessageStyle={{ display: 'none' }}
                        classes="w-100"
                    >
                        <div
                            className={`drop-zone-style ${isDragging ? "is-dragging" : ""} ${file ? "drop-zone-active" : ""} ${deshabilitado ? "offline-mode" : ""}`}
                            style={{
                                width: "100%",
                                minHeight: "100px",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                cursor: deshabilitado ? "not-allowed" : "pointer",
                                border: "2px dashed #ccc" // Asegúrate de mantener un diseño similar al anterior aquí
                            }}
                        >
                            {isDragging ? (
                                <p className="m-0">Suelta la imagen</p>
                            ) : file ? (
                                <span className="success-message">✓ {file.name}</span>
                            ) : deshabilitado ? (
                                <p className="m-0">Estas sin conexión</p>
                            ) : null 
                            }
                        </div>
                    </FileUploader>
                </div>

                {/* Submit Button */}
                <button type="submit" className="btn btn-custom w-100" disabled={deshabilitado}>
                    {deshabilitado ? "Sin conexión" : "+ Subir Producto"}
                </button>

                {alerta.visible && (
                    <div className={`alert alert-${alerta.tipo} mt-3`}>{alerta.texto}</div>
                )}
            </form>
        </div>
    );
};

export default FormularioNuevosProductos;
